'use strict';
let materialWindow=null;
function openMaterial(url){try{if(!materialWindow||materialWindow.closed){materialWindow=window.open('about:blank','zpe-material');if(materialWindow)materialWindow.opener=null;}if(materialWindow){materialWindow.location.href=url;materialWindow.focus();}else{announce('Przeglądarka zablokowała drugą kartę. Zezwól na jej otwarcie dla strony szkolenia.');}}catch{materialWindow=window.open(url,'_blank','noopener');}}
const D=window.WORKSHOP, KEY='zpe-warsztat-v1', main=document.getElementById('main');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isZpe=u=>{try{const x=new URL(u);return x.protocol==='https:'&&(x.hostname==='zpe.gov.pl'||x.hostname.endsWith('.zpe.gov.pl'));}catch{return false;}};
let state={lesson:{},completed:[],assessment:{},partner:'',support:'',slide:1}, storageOK=true, filter='all';
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved)){for(const [k] of D.fields)if(typeof saved.lesson?.[k]==='string')state.lesson[k]=saved.lesson[k];state.completed=Array.isArray(saved.completed)?saved.completed.filter(n=>Number.isInteger(n)&&n>=1&&n<=12):[];for(let i=0;i<D.checks.length;i++)if(D.statuses.includes(saved.assessment?.[i]))state.assessment[i]=saved.assessment[i];state.partner=typeof saved.partner==='string'?saved.partner:'';state.support=typeof saved.support==='string'?saved.support:'';state.slide=Number.isInteger(saved.slide)&&saved.slide>=1?saved.slide:1;}}
catch{storageOK=false;warn('Nie udało się odczytać zapisu. Możesz pracować dalej; zachowaj plan przyciskiem „Pobierz kopię tekstową”.');}
function warn(t){const n=document.getElementById('storage-warning');n.hidden=false;n.textContent=t;}
function announce(t){document.getElementById('announcement').textContent=t;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;document.getElementById('storage-warning').hidden=true;}catch{storageOK=false;warn('Przeglądarka nie pozwala zapisać zmian. Treść pozostaje na tej stronie do jej zamknięcia. Pobierz kopię tekstową lub wydrukuj plan.');}const n=document.getElementById('save-status');if(n)n.textContent=storageOK?'Zapisano w tej przeglądarce. Trener nie otrzymuje tych zapisów.':'Zapis lokalny niedostępny. Pobierz kopię tekstową przed zamknięciem strony.';}
function link(url,label,cls=''){const external=/^https:\/\//.test(url);return `<a class="${cls}" href="${esc(url)}"${external?' target="zpe-material" rel="noopener"':''}>${esc(label)}${external?'<span class="sr-only"> (otwiera materiał w drugiej karcie)</span>':''}</a>`;}
const button=(label,action,cls='secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const list=items=>`<ol class="tasks">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;
function field(k,label,placeholder=''){const short=['topic','group','title','url','date'].includes(k),value=state.lesson[k]||'';return `<div class="field"><label for="f-${k}">${esc(label)}</label>${short?`<input id="f-${k}" name="${k}" ${k==='url'?'type="url" inputmode="url"':''} value="${esc(value)}" placeholder="${esc(placeholder)}" maxlength="3000">`:`<textarea id="f-${k}" name="${k}" placeholder="${esc(placeholder)}" maxlength="8000">${esc(value)}</textarea>`}</div>`;}
function resources(embed=false){const rs=D.resources.filter(r=>filter==='all'||r.kind===filter);return `<div class="wrap" id="resources-box" data-embed="${embed?1:0}">${embed?'':'<h1>Wybierz jeden materiał</h1><p class="lede">Zacznij od tematu swojej lekcji. Wystarczy jeden fragment i jedno dobre polecenie.</p>'}<p class="small">Podane czasy to propozycje pracy z fragmentem, nie długości całych materiałów. Linki otwierają ZPE w drugiej karcie; do instrukcji wrócisz kartą „ZPE bez pośpiechu”.</p><div class="filters" aria-label="Rodzaj materiałów">${[['all','Wszystkie (8)'],['ogólne','Ogólnokształcące (4)'],['zawodowe','Zawodowe (4)']].map(([v,t])=>button(t,'filter','secondary',`data-filter="${v}" aria-pressed="${filter===v}"`)).join('')}</div><p id="resource-count" class="small" aria-live="polite">Widoczne materiały: ${rs.length}.</p><div class="resource-list">${rs.map(r=>`<article class="resource"><p class="small">${esc(r.subject)} · około ${r.minutes} min</p><h2>${esc(r.title)}</h2><dl><dt>Co otworzyć</dt><dd>${esc(r.fragment)}</dd><dt>Propozycja polecenia</dt><dd>${esc(r.task)}</dd><dt>Co sprawdzić</dt><dd>${esc(r.evidence)}</dd></dl><details><summary>Wskazówka do wyboru</summary><p>${esc(r.note)}</p></details><div class="actions">${link(r.url,'Otwórz w ZPE','button')}${button('Wpisz tytuł i link do planu','select-resource','secondary',`data-id="${r.id}"`)}</div></article>`).join('')}</div><p class="small section">Dobór i propozycje poleceń: opracowanie autorskie warsztatu. Dostępność publicznych stron sprawdzona ${D.date}. ${link('#/zrodla','Źródła i zakres weryfikacji')}.</p></div>`;}
function example(){return `<div class="example">${['topic','goal','fragment','duration','task','answer','check'].map(k=>`<p><strong>${esc(D.fields.find(f=>f[0]===k)[1])}</strong><br>${esc(D.example[k])}</p>`).join('')}${link(D.example.url,'Otwórz materiał przykładowej lekcji')}</div>`;}
function lesson(embed=false){return `<div class="wrap">${embed?'':'<h1>Moja lekcja z ZPE</h1><p class="lede">Wypełnij plan małego fragmentu. Możesz zacząć na papierze i wrócić tutaj później.</p>'}<p class="save-status" id="save-status" role="status">${storageOK?'Zapisy pozostają w tej przeglądarce. Trener ich nie otrzymuje.':'Zapis lokalny niedostępny. Pobierz kopię przed zamknięciem.'}</p><div class="form-layout"><form id="lesson-form" novalidate><fieldset class="form-group"><legend>1. Twoja klasa i cel</legend>${D.fields.slice(0,4).map(f=>field(...f)).join('')}</fieldset><fieldset class="form-group"><legend>2. Materiał i zadanie</legend>${D.fields.slice(4,11).map(f=>field(...f)).join('')}<p id="url-error" class="error" role="status"></p>${button('Sprawdź link i otwórz materiał','open-lesson','secondary')}</fieldset><fieldset class="form-group"><legend>3. Poprawka i pierwsze użycie</legend>${D.fields.slice(11).map(f=>field(...f)).join('')}</fieldset><p id="completeness" role="status"></p><div class="actions">${button('Sprawdź kompletność','validate','secondary')}${link('#/druk-planu','Podgląd i druk planu','button')}${button('Pobierz kopię tekstową','download')}</div><p class="small">Wydruk lub plik tekstowy pozwoli zachować plan także poza tą przeglądarką. Przeniesienie strony na inny adres nie przenosi zapisów.</p></form><aside class="form-side"><h2>Pomoc przy pisaniu</h2><p><strong>Mały cel:</strong> uczeń porównuje, wybiera, wyjaśnia lub oblicza jedną rzecz.</p><p><strong>Konkretny efekt:</strong> po działaniu zostaje odpowiedź, decyzja albo krótka notatka.</p><p><strong>Czas na sprawdzenie:</strong> uwzględnij go w swoich 10–15 minutach.</p><details><summary>Gotowy przykład 12-minutowej lekcji</summary>${example()}</details>${embed?'':link('#/materialy','Wróć do wyboru materiału')}<p class="small section">Nie wpisuj danych uczniów ani haseł. Na tej stronie przygotowujesz własną notatkę.</p></aside></div></div>`;}
function imageFigure(name,alt,source){return `<figure><a href="assets/${name}" target="zpe-ilustracja" rel="noopener"><img class="instruction-image" src="assets/${name}" alt="${esc(alt)}" loading="lazy"></a><figcaption class="caption">Ilustracja z oficjalnego poradnika ZPE, pobrana ${D.date}. Kliknij ilustrację, aby ją powiększyć. ${link(source,'Źródło')}.</figcaption></figure>`;}
function cardsHTML(){return `<article class="print-card"><p class="eyebrow">Karta 1</p><h2>Pierwsze kroki</h2><p>Cel: otworzyć ZPE, przełączyć kartę i wrócić do instrukcji.</p><dl><dt><strong>Przeglądarka</strong></dt><dd>Program do otwierania stron, np. Chrome, Edge, Firefox lub Safari.</dd><dt><strong>Pasek adresu</strong></dt><dd>Pole na górze okna. Kliknij je, wpisz <strong>zpe.gov.pl</strong> i naciśnij Enter.</dd><dt><strong>Link</strong></dt><dd>Klikany tekst lub przycisk, który otwiera stronę.</dd><dt><strong>Karta przeglądarki</strong></dt><dd>Zakładka z tytułem u góry. Kliknij jej tytuł, aby wrócić do szkolenia.</dd></dl><h3>Przećwicz trzy czynności</h3>${list(['Przewijanie: kółko myszy lub dwa palce przesuwane po płytce laptopa.','Powiększanie: menu przeglądarki → Powiększenie → plus. Skrót: Ctrl i + (Mac: Cmd i +).','Kopiowanie adresu: kliknij pasek adresu, zaznacz cały adres (Ctrl+A), skopiuj (Ctrl+C). Kliknij pole „Link” w swoim planie i wklej (Ctrl+V). Na Macu używaj Cmd zamiast Ctrl.'])}<p class="done-box">Sprawdzam: potrafię otworzyć ZPE i wrócić do karty szkolenia.</p><h3>Jeśli coś się nie zgadza</h3><p>Zatrzymaj się. Powiedz, na którym kroku jesteś. Nie zamykaj całego programu. Hasło wpisuj tylko w ZPE, samodzielnie.</p></article>
<article class="print-card"><p class="eyebrow">Karta 2A</p><h2>Znajduję materiał</h2>${list(['Na ZPE otwórz Katalog i pole wyszukiwania.','Wpisz „Gdzie tego szukać? O notowaniu”. Uruchom wyszukiwanie.','Otwórz materiał o tym tytule. Znajdź początkowy fragment o formach notatki.','Przy własnym temacie możesz ograniczyć wyniki do etapu i przedmiotu. Jeśli nie ma wyników, usuń część filtrów lub skróć hasło.'])}${imageFigure('wyszukiwanie.png','Oficjalny przykład wyszukiwania: pole zapytania oraz wybór etapu edukacyjnego i przedmiotu. Ilustracja pokazuje komórkę, na warsztacie wpisujemy tytuł o notowaniu.',D.sources[0][1])}<p>Ilustracja pokazuje przykład biologiczny z poradnika. Na warsztacie wpisz wskazany tytuł o notowaniu.</p><p class="caption">Wygląd ekranu porównaj z pokazem prowadzącego. Ilustracja pochodzi z poradnika, a nie z konta uczestnika.</p><p>Mój temat wyszukiwania:</p><div class="line"></div></article>
<article class="print-card"><p class="eyebrow">Karta 2B</p><h2>Zapisuję i wracam</h2>${list(['Zaloguj się na własne konto ZPE.','W materiale kliknij serce „Dodaj do ulubionych”. Drugie kliknięcie może usunąć zapis.','Otwórz Katalog → Ulubione. Odszukaj tytuł i ponownie go otwórz.'])}${imageFigure('ulubione-serce.png','Oficjalny przykład pokazujący ikonę serca na stronie materiału ZPE.',D.sources[1][1])}${imageFigure('ulubione-katalog.png','Oficjalny przykład menu Katalog z pozycją Ulubione.',D.sources[1][1])}<p class="done-box">Sprawdzam: materiał jest na mojej liście i otwieram go przez tę listę.</p><p class="caption">Bez zalogowania możesz oglądać materiał. Samo otwarcie nie potwierdza zapisania w Ulubionych. Operację na koncie sprawdza uczestnik z prowadzącym.</p></article>
<article class="print-card"><p class="eyebrow">Karta 3</p><h2>Pomagamy sobie w parze</h2><p><strong>Każdy obsługuje własny laptop. Zmieniamy role.</strong></p><h3>Osoba ćwicząca</h3>${list(['Otwórz Ulubione.','Wybierz zapisany materiał.','Pokaż dokładny fragment.','Powiedz, co mogliby zrobić z nim uczniowie.'])}<h3>Osoba wspierająca pyta</h3><ul><li>Na którym kroku teraz jesteś?</li><li>Co widzisz na ekranie i jak to się nazywa?</li><li>Jaki następny krok wskazuje instrukcja?</li></ul><p>Wskazuj instrukcję i daj czas na próbę. Nie przejmuj myszy. Nie odczytuj hasła drugiej osoby.</p><h3>Teraz zamiana</h3><p>Druga osoba powtarza procedurę na swoim komputerze. Na końcu każdy wykonuje ją jeszcze raz samodzielnie.</p><h3>Próba własnego polecenia</h3><p>„Wiem, co mam zrobić…”</p><div class="line"></div><p>„Potrzebuję doprecyzowania…”</p><div class="line"></div><p>Jedna zmiana w moim poleceniu:</p><div class="write-area"></div></article>
${[D.fields.slice(0,7),D.fields.slice(7)].map((fields,i)=>`<article class="print-card"><p class="eyebrow">Karta 4${i?'B':'A'}</p><h2>${i?'Zadanie i sprawdzenie':'Moja lekcja z ZPE'}</h2><p>Plan na 10-15 minut. Możesz też skorzystać z formularza na stronie.</p>${fields.map(f=>`<div class="field"><strong>${esc(f[1])}</strong><div class="line"></div></div>`).join('')}<p>Sprawdzam: mam cel, działający link, nazwę fragmentu, polecenie, odpowiedź i czas na sprawdzenie.</p></article>`).join('')}
<article class="print-card"><p class="eyebrow">Karta 5</p><h2>Potrafię wrócić</h2><p>Najpierw wykonaj czynność, potem zaznacz status. S = samodzielnie, Ś = ze ściągą, P = potrzebuję pomocy.</p><table><thead><tr><th>Czynność</th><th>S</th><th>Ś</th><th>P</th></tr></thead><tbody>${D.checks.map(c=>`<tr><td>${esc(c)}</td><td>○</td><td>○</td><td>○</td></tr>`).join('')}</tbody></table><p style="margin-top:20px">Partner potwierdza wykonane czynności (numery, inicjały):</p><div class="line"></div><p>Potrzebuję jeszcze pomocy przy:</p><div class="write-area"></div><p>Wykorzystam materiał: klasa / dzień</p><div class="line"></div><h3>Powrót po czasie</h3><p><strong>Po 2 dniach:</strong> otwórz ZPE i znajdź zasób przez Ulubione.</p><p><strong>Po 7 dniach:</strong> użyj fragmentu na lekcji lub przećwicz go ponownie.</p><p><strong>Po 7–14 dniach:</strong> odpowiedz organizatorowi: czy użyto materiału, co zrobili uczniowie i jaka pomoc jest potrzebna?</p><p>Oddaj tę kartę trenerowi, jeśli zbiera wyniki. Strona nie wysyła mu odpowiedzi.</p></article>
<article class="print-card"><h2>Sygnały na stolik</h2><p>Wytnij trzy części. Połóż na stoliku komunikat, który opisuje obecną sytuację.</p><div class="signal">PRACUJĘ</div><div class="signal">GOTOWE</div><div class="signal">POTRZEBUJĘ POMOCY</div></article>`;}
function cards(print=false){return `<div class="wrap"><div class="screen-only"><h1>Karty pracy</h1><p class="lede">Ściągi do położenia obok komputera. Pięć kart tematycznych i sygnały pomocy; karta 2 ma dwie części.</p><div class="actions">${link('output/pdf/karty-uczestnika.pdf','Pobierz karty PDF','button')}${print?button('Drukuj karty','print','secondary'):link('#/druk-kart','Podgląd wydruku','button secondary')}</div></div>${cardsHTML()}</div>`;}
function checkView(embed=false){return `<div class="wrap">${embed?'':'<h1>Potrafię wrócić</h1><p class="lede">Wykonaj czynności na swoim koncie ZPE. Potem zaznacz, jakiej pomocy potrzebujesz.</p>'}<form id="assessment">${D.checks.map((c,i)=>`<div class="check-row"><fieldset><legend>${i+1}. ${esc(c)}</legend>${D.statuses.map((s,j)=>`<label><input type="radio" name="check-${i}" value="${esc(s)}" ${state.assessment[i]===s?'checked':''}>${esc(s)}</label>`).join('')}</fieldset></div>`).join('')}<div class="field"><label for="partner">Potwierdzenie partnera: numery wykonanych czynności i inicjały</label><input id="partner" name="partner" value="${esc(state.partner)}" maxlength="1000"></div><div class="field"><label for="support">Potrzebuję pomocy przy…</label><textarea id="support" name="support" maxlength="3000">${esc(state.support)}</textarea></div></form><p class="save-status" id="save-status">Te odpowiedzi pozostają w tej przeglądarce.</p><div class="actions">${link('#/druk-sprawdzenia','Podgląd i druk odpowiedzi','button')}${embed?'':link(stageHref(12),'Przejdź do zakończenia','button secondary')}</div><p>Trener zobaczy Twoją kartę dopiero, gdy mu ją pokażesz lub przekażesz wydruk.</p></div>`;}
function demo(){return `<section><h2>Pokaz kursu w 10 minut</h2><p>Uczestnicy obserwują. Nie powtarzają operacji na własnych kontach.</p><ol><li><strong>3 min:</strong> w materiale wybierz Udostępnij → Platforma edukacyjna → Nowy kurs.</li><li><strong>3 min:</strong> omów różnicę między „Zapisz” i „Opublikuj” oraz potrzebę przypisania uczniów. Posługuj się kontami testowymi lub ilustracjami oficjalnej instrukcji.</li><li><strong>3 min:</strong> pokaż zakładkę Analiza, a następnie omów poniższy przypadek.</li><li><strong>1 min:</strong> zapytaj: „Czy zwykły link daje raport ucznia?”. Odpowiedź: nie.</li></ol><div class="task-box"><h3>Przykład dydaktyczny, dane fikcyjne</h3><p>To autorski przykład do rozmowy, nie zrzut ani odwzorowanie raportu ZPE.</p><table><thead><tr><th>Osoba testowa</th><th>Odpowiedź na pytanie: jaka forma ułatwia porównanie?</th></tr></thead><tbody><tr><td>A</td><td>Tabela, bo widzę te same cechy obok siebie.</td></tr><tr><td>B</td><td>Punkty, bo zawsze są najlepsze.</td></tr><tr><td>C</td><td>Brak odpowiedzi.</td></tr></tbody></table><p style="margin-top:20px"><strong>Decyzja nauczyciela:</strong> A uzasadnia wybór celem. B potrzebuje porównania dwóch form na konkretnym przykładzie. Przy C najpierw sprawdzamy dostęp i zrozumienie polecenia; brak odpowiedzi nie dowodzi braku chęci.</p><p>Czas wyświetlania nie mierzy uwagi ucznia. Nie wykorzystuj go jako automatycznej oceny zaangażowania.</p></div><p>${link(D.sources[4][1],'Instrukcja dodawania materiału do kursu')}<br>${link(D.sources[5][1],'Instrukcja publikacji i zapisów')}<br>${link(D.sources[6][1],'Instrukcja raportów i ich ilustracje')}</p></section>`;}
function trainer(print=false){return `<div class="wrap"><div class="screen-only"><h1>Scenariusz prowadzącego</h1><p class="lede">40 osób, 20 par, jeden trener. Każdy kończy z własnym fragmentem lekcji.</p><div class="actions">${link('output/pdf/scenariusz-trenera.pdf','Pobierz scenariusz PDF','button')}${print?button('Drukuj scenariusz','print'):link('#/druk-trenera','Podgląd wydruku','button secondary')}</div></div><section><h2>Prowadzenie z prezentacji</h2><p>Szkolenie jest jedną prezentacją: slajdy pokazowe przeplatają się z zadaniami dla uczestników. Każdy uczestnik ma ją otwartą na swoim laptopie, a prowadzący wyświetla ją na projektorze. Etap 1 to wstęp „Lekcja, w której pracują uczniowie”: ${link('#/wstep','slajdy '+idx('teza')+'–'+idx('zadanie-1'))}. W PDF scenariusza wstęp jest na stronach 2–6.</p><p><strong>Sterowanie:</strong> strzałka w prawo, PageDown lub spacja przechodzi dalej. Na długich slajdach PageDown i spacja najpierw przewijają treść. Strzałka w lewo cofa. <strong>N</strong> pokazuje i ukrywa notatki prowadzącego, <strong>M</strong> otwiera spis slajdów. Pilot do prezentacji działa jak PageDown i PageUp. Na telefonie przesuń palcem w bok.</p></section><section class="section"><h2>Przygotowanie przed szkoleniem</h2><p>Cel: uczestnik odnajduje, zapisuje i ponownie otwiera materiał oraz przygotowuje własne polecenie z kryterium odpowiedzi.</p>${list(D.preflight)}<div class="notice"><strong>Zakres weryfikacji pakietu</strong><p>Publiczne strony i oficjalne instrukcje sprawdzono ${D.date}. Nie wykonano próby na zalogowanym koncie ZPE, pilotażu z dwiema osobami ani testu sieci w sali. Te czynności wykonuje organizator przed zajęciami.</p></div></section><section class="section"><h2>Jak utrzymać wspólne tempo</h2><p>Pokaz 2–4 minuty, wykonanie, sprawdzenie. Nie tłumacz podczas samodzielnej próby. Cztery pary zgłaszające ten sam błąd to sygnał do powtórzenia kroku całej grupie. Osoby szybsze przygotowują drugie polecenie do tego samego zasobu.</p><p>Pary zmieniają role. Osoba wspierająca wskazuje instrukcję, a ćwicząca obsługuje własny komputer. Brak logowania odnotuj osobno; nie uznawaj przeglądania publicznej strony za zaliczony zapis w Ulubionych.</p></section><section class="section"><h2>Harmonogram 180 minut</h2><div class="table-wrap"><table><thead><tr><th>Minuty</th><th>Etap</th><th>Efekt</th></tr></thead><tbody>${D.stages.map((s,i)=>`<tr><td>${s.time.join('–')}</td><td>${link(stageHref(i+1),s.title)}</td><td>${esc(s.done)}</td></tr>`).join('')}</tbody></table></div></section><section class="section"><h2>Wariant 120 minut</h2><table><thead><tr><th>Minuty</th><th>Etap</th></tr></thead><tbody>${D.short.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table><p>W parze przeznacz 2 minuty na instrukcję, po 5 na każdą rolę i 3 na domknięcie. Zakończenie: 10 minut samodzielnej próby, 5 na plan wdrożenia. Pomijasz drugą przerwę, osobny test poleceń i pokaz kursów.</p></section><section class="section"><h2>Przebieg i interwencje</h2>${D.stages.map((s,i)=>`<article class="trainer-stage"><p class="small">${s.time.join('–')} min · etap ${i+1}</p><h3>${esc(s.title)}</h3><dl><dt>Cel</dt><dd>${esc(s.goal)}</dd><dt>Przygotuj</dt><dd>${esc(s.prep)}</dd><dt>Powiedz</dt><dd class="quote">„${esc(s.say)}”</dd><dt>Poprowadź</dt><dd>${esc(s.run)}</dd><dt>Uczestnik wykonuje</dt><dd>${list(s.steps)}</dd><dt>Sprawdź efekt</dt><dd>${esc(s.done)}</dd><dt>Typowa trudność</dt><dd>${esc(s.error)}</dd><dt>Jak pomóc</dt><dd>${esc(s.help)}</dd></dl></article>`).join('')}</section><section class="section">${demo()}</section><section class="section"><h2>Przykład całego produktu uczestnika</h2>${example()}</section><section class="section"><h2>Plan awaryjny</h2><p><strong>Awaria internetu:</strong> wykorzystaj karty, ilustracje i poniższy autorski przykład. Uczestnicy układają cel, polecenie i odpowiedź na papierze. Sprawdzenie techniczne przenieś na termin z dostępem do ZPE.</p><div class="task-box"><h3>Przykład do pracy bez internetu</h3><p>Tabela ułatwia zestawienie tych samych cech dwóch obiektów. Punkty pomagają zapisać kolejność czynności. Schemat pokazuje relacje między elementami.</p><p><strong>Polecenie:</strong> dobierz formę do porównania dwóch telefonów oraz do zapisania kolejności przygotowania stanowiska pracy. Uzasadnij jeden wybór.</p><p><strong>Kryterium:</strong> tabela do porównania, punkty do kolejności; inna propozycja jest dopuszczalna, jeśli uczestnik wyjaśni, jak spełni cel.</p></div></section><section class="section"><h2>Ocena i powrót po szkoleniu</h2><p>Zbierz papierowe karty 5. Zapisz liczbę osób w trzech statusach dla każdej czynności. Obserwuj osoby proszące o pomoc i wybrane pozostałe stanowiska. Potwierdzenie partnera jest dodatkową informacją, nie dowodem zweryfikowanym przez trenera.</p><p>Po 7–14 dniach organizator zbiera odpowiedzi na trzy pytania: Czy wykorzystano materiał? Co konkretnie zrobili uczniowie? Przy czym potrzebne jest wsparcie? Nie wysyłamy automatycznych wiadomości z tej strony.</p></section><section class="section"><h2>Metody i źródła</h2>${D.sources.slice(8).map(s=>`<p>${link(s[1],s[0])}: ${esc(s[2])}</p>`).join('')}<p>To adaptacja metod do warsztatu dorosłych. ${link('#/zrodla','Pełna kwerenda i źródła ilustracji')}.</p></section></div>`;}
function printLesson(){return `<div class="wrap"><div class="screen-only"><h1>Podgląd własnego planu</h1><p>Wybierz „Drukuj”, a następnie drukarkę lub „Zapisz jako PDF”.</p><div class="actions">${button('Drukuj plan','print','')}${link('#/moja-lekcja','Wróć do edycji','button secondary')}</div></div><article><h2>Moja lekcja z ZPE</h2>${D.fields.map(([k,t])=>`<section class="no-break"><h3>${esc(t)}</h3><p class="print-value">${esc(state.lesson[k]||'Do uzupełnienia')}</p></section>`).join('')}</article></div>`;}
function printCheck(){return `<div class="wrap"><div class="screen-only"><h1>Podgląd sprawdzenia</h1><div class="actions">${button('Drukuj odpowiedzi','print','')}${link('#/sprawdzenie','Wróć','button secondary')}</div></div><h2>Potrafię wrócić</h2>${D.checks.map((c,i)=>`<p><strong>${i+1}. ${esc(c)}</strong><br>${esc(state.assessment[i]||'Nie zaznaczono statusu')}</p>`).join('')}<p><strong>Potwierdzenie partnera:</strong> ${esc(state.partner||'Nie wpisano')}</p><p><strong>Potrzebuję pomocy przy:</strong> ${esc(state.support||'Nie wpisano')}</p><p><strong>Termin i klasa:</strong> ${esc(state.lesson.date||'Nie wpisano')}</p></div>`;}
function sources(){return `<div class="wrap"><h1>Źródła i informacje</h1><p class="lede">Kwerenda publicznych materiałów ZPE i inspiracji metodycznych. Stan przeglądu: ${D.date}.</p><div class="notice"><p><strong>Co sprawdzono:</strong> dostępność i opisy publicznych zasobów oraz ścieżkę opisaną w poradnikach ZPE. Nie potwierdzono operacji na zalogowanym koncie ani działania wszystkich interaktywnych elementów i raportów. Czas ostatniego indeksowania strony nie oznacza daty aktualizacji materiału.</p></div><h2>Instrukcje i metody</h2>${D.sources.map(s=>`<section class="source-item"><h3>${link(s[1],s[0])}</h3><p>${esc(s[2])}</p></section>`).join('')}<h2 class="section">Zestaw startowy</h2>${D.resources.map(r=>`<section class="source-item"><h3>${link(r.url,r.title)}</h3><p>${esc(r.subject)}. ${esc(r.note)}</p></section>`).join('')}<h2 class="section">Ilustracje</h2><p>Trzy niezmienione ilustracje z publicznych instrukcji ZPE, pobrane ${D.date}: wyszukiwanie z filtrami, ikona serca i menu Ulubione. Źródła: ${link(D.sources[0][1],'Wyszukiwanie materiałów')} i ${link(D.sources[1][1],'Ulubione')}. To ilustracje poradnika, a nie zrzuty wykonane na koncie uczestnika.</p><h2 class="section">Prywatność i zapis</h2><p>Pakiet nie ma kont, analityki ani serwera zbierającego odpowiedzi. Plan i samoocena zapisują się w pamięci tej przeglądarki. Czyszczenie danych witryny może je usunąć. Użyj wydruku lub kopii tekstowej, aby zachować plan poza przeglądarką. Otwarcie ZPE prowadzi do zewnętrznego serwisu, który ma własne zasady korzystania.</p><p>Materiały warsztatu są autorskim opracowaniem na podstawie podanych źródeł. Pakiet nie jest oficjalną instrukcją Ministerstwa Edukacji ani ZPE.</p></div>`;}
function knowledge(){const groups=[...new Set(D.knowledge.map(x=>x.group))];return `<div class="wrap"><h1>Baza wiedzy ZPE</h1><p class="lede">Praktyczna mapa funkcji z jedenastu przekazanych instrukcji. Na szkoleniu ćwiczymy podstawową ścieżkę; pozostałe tematy zostają jako przewodnik do dalszej pracy.</p><div class="notice"><p><strong>Jak czytać tę bazę:</strong> zielone oznaczenie wskazuje funkcje ćwiczone lub pokazywane 4 listopada. Pozostałe funkcje są materiałem po szkoleniu. Poradniki pokazują różne generacje interfejsu, więc przed użyciem sprawdź nazwy przycisków na swoim koncie.</p></div>${groups.map(g=>`<section class="section"><h2>${esc(g)}</h2><div class="resource-list">${D.knowledge.filter(x=>x.group===g).map(x=>`<article class="resource"><p class="small">${x.live?'● Na szkoleniu':'○ Po szkoleniu'}</p><h3>${esc(x.title)}</h3><dl><dt>Po co</dt><dd>${esc(x.purpose)}</dd><dt>Typowa droga</dt><dd>${esc(x.path)}</dd><dt>Praktycznie</dt><dd>${esc(x.practice)}</dd><dt>Uwaga</dt><dd>${esc(x.caution)}</dd></dl><details><summary>Źródło w przekazanych PDF-ach</summary><p>${esc(x.source)}</p></details></article>`).join('')}</div></section>`).join('')}<section class="section"><h2>Najkrótsza droga na pierwszą lekcję</h2><ol class="tasks"><li>Wybierz konkretny temat i jedną czynność ucznia.</li><li>Znajdź jeden krótki fragment w ZPE.</li><li>Zapisz go w Ulubionych oraz zachowaj pełny link.</li><li>Dopisz polecenie, oczekiwaną odpowiedź i sposób sprawdzenia.</li><li>Przetestuj polecenie z drugą osobą i zaplanuj wersję bez internetu.</li></ol><div class="actions">${link('#/moja-lekcja','Przygotuj własną lekcję','button')}${link('#/zrodla','Źródła i zakres weryfikacji','button secondary')}</div></section></div>`;}
function guides(){return `<div class="wrap"><h1>Indeks 11 poradników ZPE</h1><p class="lede">Dokładna mapa przekazanych PDF-ów: co zawiera każdy dokument i gdzie jego treść została wykorzystana w szkoleniu.</p><div class="notice"><p>Łącznie przeanalizowano <strong>${D.pdf_guides.reduce((a,x)=>a+x.pages,0)} stron</strong>. Dokumenty pokazują różne wersje interfejsu. Indeks służy do wyboru właściwego poradnika; aktualne czynności trzeba potwierdzić na koncie ZPE.</p></div><div class="resource-list">${D.pdf_guides.map((g,i)=>`<article class="resource"><p class="small">Poradnik ${i+1} z ${D.pdf_guides.length} · ${g.pages} stron</p><h2>${esc(g.title)}</h2><h3>Zakres</h3><ul>${g.topics.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Jak wykorzystano</h3><p>${esc(g.used)}</p><div class="actions">${link(g.file,'Otwórz oryginalny PDF','button secondary')}</div></article>`).join('')}</div><div class="actions section">${link('#/baza-wiedzy','Przejdź do praktycznej bazy wiedzy','button')}${link('#/centrum-materialow','Wróć do wszystkich materiałów','button secondary')}</div></div>`;}
function materialsCenter(){return `<div class="wrap"><h1>Materiały do szkolenia i po szkoleniu</h1><p class="lede">Wszystko w jednym miejscu: przebieg spotkania, praca własna, instrukcje, rozszerzenia i pliki do pobrania.</p><section class="section"><h2>4 listopada — klikaj dalej</h2><div class="resource-list"><article class="resource"><h3>Prezentacja i zadania</h3><p>Jedna ścieżka prowadzi przez trzy części szkolenia. Po wykonaniu zadania zaznacz etap i kliknij „Dalej”.</p><div class="actions">${link('#/s/1','Rozpocznij szkolenie','button')}</div></article><article class="resource"><h3>Moja lekcja</h3><p>Formularz produktu końcowego: cel, materiał, polecenie, odpowiedź, sprawdzenie i plan bez internetu.</p><div class="actions">${link('#/moja-lekcja','Otwórz formularz','button')}</div></article><article class="resource"><h3>Zestaw startowy</h3><p>Osiem materiałów ZPE: cztery ogólnokształcące i cztery zawodowe, każdy z propozycją zadania.</p><div class="actions">${link('#/materialy','Wybierz materiał','button')}</div></article><article class="resource"><h3>Sprawdzenie końcowe</h3><p>Samodzielny powrót do zasobu i uczciwa informacja, przy czym nadal potrzebujesz pomocy.</p><div class="actions">${link('#/sprawdzenie','Wykonaj sprawdzenie','button')}</div></article></div></section><section class="section"><h2>Baza wiedzy i rozszerzenia</h2><div class="resource-list"><article class="resource"><h3>Baza wiedzy ZPE</h3><p>Dziesięć obszarów: od wyszukiwania do Kreatora, ścieżek nauki, komunikacji i funkcji zaawansowanych.</p><div class="actions">${link('#/baza-wiedzy','Otwórz bazę','button')}</div></article><article class="resource"><h3>Indeks przekazanych PDF-ów</h3><p>Jedenaście poradników, ${D.pdf_guides.reduce((a,x)=>a+x.pages,0)} stron, zakres każdego dokumentu i sposób wykorzystania.</p><div class="actions">${link('#/poradniki','Otwórz indeks','button')}</div></article><article class="resource"><h3>Od materiału do wyników</h3><p>Pokaz różnicy między zwykłym linkiem, przypisaną pracą i raportem oraz przykład decyzji nauczyciela.</p><div class="actions">${link('#/pokaz','Otwórz rozszerzenie','button')}</div></article><article class="resource"><h3>Metody pracy z technologią</h3><p>Dwanaście modeli lekcji z planami, przykładami i oceną siły dowodów.</p><div class="actions">${link('https://metodyka.covepolska.pl/','Otwórz katalog','button')}</div></article></div></section><section class="section"><h2>Pliki do pobrania i wydruku</h2><div class="actions">${link('output/pdf/karty-uczestnika.pdf','Karty uczestnika PDF','button')}${link('output/pdf/scenariusz-trenera.pdf','Scenariusz prowadzącego PDF','button')}${link('#/karty','Karty w wersji internetowej','button secondary')}${link('#/trener','Scenariusz w wersji internetowej','button secondary')}</div></section></div>`;}
// ── Prezentacja: jedna ścieżka slajdów od wstępu do zakończenia ──
const I=D.intro,DK=D.deck,WHO={n:'mówi nauczyciel',u:'pracuje uczeń',p:'pracuje para',k:'rozmowa klasy'};
const ext=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener">${esc(label)}<span class="sr-only"> (otwiera się w nowej karcie)</span></a>`;
const li=x=>`<li>${esc(x)}</li>`;
const pills=m=>m.split('; ').map(x=>`<span class="pill">${esc(x)}</span>`).join('');

const isBreak=n=>n===5||n===8;
let SLIDES=[],current=1,mode='deck',timerId=null,lessonStep=2,notesOpen=false;
try{notesOpen=localStorage.getItem('zpe-notes')==='1';}catch{}
const idx=key=>SLIDES.findIndex(s=>s.key===key||s.key===key.replace(/^etap-/,'zadanie-'))+1;
const stageHref=(n,task=false)=>'#/s/'+idx(task&&!isBreak(n)?'zadanie-'+n:'etap-'+n);
const go=n=>{n=Math.max(1,Math.min(SLIDES.length,n));if(mode==='deck'&&n===current)return;location.hash='/s/'+n;};
const nav=(label,action,cls='btn btn-primary')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;

function titleSlide(){const cont=state.slide>2&&state.slide<=SLIDES.length;return `<svg class="deco" viewBox="0 0 1200 700" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path d="M -120 620 Q 380 -80 1320 240" stroke="#0077cc" stroke-width="220" fill="none" stroke-opacity="0.04"/><path d="M -80 700 Q 480 80 1320 420" stroke="#e8a020" stroke-width="80" fill="none" stroke-opacity="0.05"/><circle cx="1100" cy="80" r="180" fill="#0077cc" opacity="0.03"/></svg><p class="section-label as">${esc(DK.label)}</p><h1 class="big-title at">ZPE bez pośpiechu</h1><p class="big-sub a1">${esc(DK.sub)}</p><div class="accent-line a2"></div><h2 class="list-head a3">Co zabierzesz ze sobą</h2><ul class="pt-list a3">${DK.outcomes.map(li).join('')}</ul><div class="actions center-actions a4">${nav('Zaczynamy →','next')}${cont?`<a class="btn btn-ghost" href="#/s/${state.slide}">Kontynuuj od slajdu ${state.slide}</a>`:''}</div><p class="facts a5">${DK.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</p><p class="nav-hint a6">Przechodzenie dalej: strzałka w prawo, przycisk „Dalej” albo kliknięcie w tło slajdu.</p>`;}
function agendaSlide(){return `<h2 class="slide-title at">Trzy części, jeden konkretny efekt</h2><div class="accent-line as"></div><p class="slide-sub a1">Zaczynamy wspólnie, potem poznajemy podstawową ścieżkę ZPE, a w pracowniach na trzecim piętrze każdy przygotowuje własny materiał.</p><div class="card-grid cg3 a2">${D.parts.map(p=>`<article class="card"><p class="small">Część ${p.n} · ${esc(p.time)}</p><h3 class="card-title">${esc(p.title)}</h3><p class="card-body">${esc(p.effect)}</p><div class="actions">${link(stageHref(p.stages[0]),'Przejdź do części','btn btn-ghost')}</div></article>`).join('')}</div><div class="key-box a3">Przyjdź z jednym konkretnym tematem ze swojego przedmiotu i własnymi materiałami, jeśli już je masz.</div>`;}
function divider(n){const s=D.stages[n-1];return `<p class="section-label at">Etap ${n} z 12</p><h2 class="big-title at">${esc(s.title)}</h2><div class="accent-line as"></div><p class="big-sub a1">${esc(s.goal)}</p><div class="key-box a2"><span class="key-label">Efekt etapu</span>${esc(s.done)}</div><ol class="stage-dots a3" aria-label="Postęp warsztatu">${D.stages.map((x,i)=>`<li class="${i+1===n?'now':''}${state.completed.includes(i+1)?' done':''}" title="${esc(x.title)}"><span class="sr-only">Etap ${i+1}: ${esc(x.title)}${i+1===n?' (teraz)':''}</span></li>`).join('')}</ol>`;}
function breakSlide(n){const s=D.stages[n-1],m=s.time[1]-s.time[0];return `<p class="section-label at">Etap ${n} z 12</p><h2 class="big-title at">${esc(s.title)}</h2><div class="accent-line as"></div><div class="timer a1"><span id="timer" class="timer-num" role="timer" data-sec="${m*60}">${m}:00</span>${nav('Uruchom odliczanie','timer','btn btn-ghost')}</div><ul class="pt-list a2">${s.steps.map(li).join('')}</ul><p class="big-sub a3">${esc(s.hint)}</p>`;}
function endSlide(){return `<p class="section-label at">Zakończenie</p><h2 class="big-title at">Dziękujemy. Teraz Twoja lekcja.</h2><div class="accent-line as"></div><p class="big-sub a1">Nie trzeba wdrażać wszystkich funkcji ZPE. Wystarczy wracać do jednego materiału i jednej lekcji, w której pracują uczniowie.</p><ol class="tl a2">${DK.end.map((x,i)=>`<li class="tl-item"><span class="tl-dot">${i+1}</span><span class="tl-body"><span class="tl-label">${esc(x[0])}</span><span class="tl-desc">${esc(x[1])}</span></span></li>`).join('')}</ol><div class="actions center-actions a3">${link('#/druk-planu','Wydrukuj mój plan','btn btn-primary')}${link('output/pdf/karty-uczestnika.pdf','Karty pracy (PDF)','btn btn-ghost')}${ext('https://metodyka.covepolska.pl/','Katalog metod COVE','btn btn-ghost')}</div>${logos('a4')}`;}
const logos=(cls='')=>`<div class="logo-row ${cls}"><img src="assets/Logo-2025.png" alt="WIN4SMEs"><img src="assets/COVE Polska bez tła.png" alt="COVE Polska"><img src="assets/PL_Co-fundedbytheEU_RGB_POS.png" alt="Współfinansowane przez Unię Europejską"></div><p class="eu-note">Finansowane ze środków Unii Europejskiej. Wyrażone poglądy nie muszą odzwierciedlać stanowiska Unii Europejskiej.</p>`;

// Wstęp (etap 1)
function timeline(segs,label){let t=0;const rows=segs.map(([m,w,x])=>{const r=[t,t+m];t+=m;return {m,w,x,r};});const sum=w=>segs.filter(s=>s[1]===w).reduce((a,s)=>a+s[0],0);return `<figure class="timeline"><figcaption><strong>${esc(label)}</strong><span>${Object.keys(WHO).filter(sum).map(w=>`<i class="dot seg-${w}"></i>${esc(WHO[w])}: ${sum(w)} min`).join('')}</span></figcaption><div class="bar" aria-hidden="true">${rows.map((r,i)=>`<span class="seg seg-${r.w}" style="flex:${r.m};--i:${i}" title="${esc(r.x)}"><b>${r.m>=8?esc(r.x):''}</b></span>`).join('')}</div><ol class="sr-only">${rows.map(r=>`<li>${esc(r.x)} (${esc(WHO[r.w])})</li>`).join('')}</ol></figure>`;}
function reveal(q,a,cls,id){return `<div class="reveal ${cls}"><p class="reveal-q"><span aria-hidden="true">❓</span> ${esc(q)}</p><button type="button" class="btn btn-ghost" data-action="reveal" aria-expanded="false" aria-controls="${id}">Pokaż odpowiedź</button><p class="reveal-a" id="${id}" hidden>${esc(a)}</p></div>`;}
function lessonStepPanel(){const s=I.lesson.steps[lessonStep];return `<p class="step-meta">${pills(s.method)}</p><h3>${esc(s.title)}</h3><dl class="role-list"><div><dt>👩‍🏫 Nauczyciel</dt><dd>${esc(s.teacher)}</dd></div><div><dt>🧑‍🎓 Uczniowie</dt><dd>${esc(s.students)}</dd></div><div><dt>💻 Urządzenie</dt><dd>${esc(s.device)}</dd></div></dl>`;}
const INTRO=[
 ['teza','Laptop, iPad i ZPE nie zmieniają lekcji same',()=>`<h2 class="slide-title at">Laptop, iPad i ZPE nie zmieniają lekcji same</h2><div class="accent-line as"></div><p class="slide-sub a1">${esc(I.lede)}</p><div class="card-grid cg3 a2">${I.thesis.map(t=>`<article class="card"><div class="card-icon" aria-hidden="true">${t.icon}</div><h3 class="card-title">${esc(t.title)}</h3><p class="card-body">${esc(t.text)}</p></article>`).join('')}</div><div class="key-box a3">${esc(I.caution)}</div>`],
 ['dwie','Dwie wersje tej samej lekcji',()=>`<h2 class="slide-title at">Dwie wersje tej samej lekcji</h2><div class="accent-line as"></div><p class="slide-sub a1">Temat, klasa i 40 minut pracy są takie same. Inny jest podział pracy.</p><div class="wide a2">${timeline(I.compare.A,'A. Wykład')}${timeline(I.compare.B,'B. Praca własna z ZPE')}</div>${reveal(I.who[0],I.who[1],'a3','who-a')}<p class="foot-note a4">${esc(I.compare_note)}</p>`],
 ['poll','Pytanie do wszystkich',()=>{const P=I.poll;return `<p class="section-label at">Teraz Państwo są uczniami · pytanie do wszystkich</p><h2 class="slide-title at">${esc(P.q)}</h2><div class="accent-line as"></div><p class="slide-sub a1">Zapisz literę na kartce. Na sygnał wszyscy pokazują odpowiedź w tej samej chwili.</p><div class="poll a2" role="group" aria-label="Odpowiedzi">${P.options.map((o,i)=>`<button type="button" class="poll-opt" data-action="poll" data-i="${i}" aria-pressed="false"><span class="poll-letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div><div class="actions center-actions a3">${nav('Pokaż odpowiedź','poll-show')}</div><div class="poll-result" id="poll-result" hidden><p><strong>Poprawnie: ${'ABCD'[P.correct]}, ${esc(P.options[P.correct])}.</strong> ${esc(P.explain)}</p><div class="key-box">${esc(P.after)}</div></div>`;}],
 ['shifts','Co laptop lub iPad z ZPE pozwala przesunąć?',()=>`<h2 class="slide-title at">Co laptop lub iPad z ZPE pozwala przesunąć?</h2><div class="accent-line as"></div><p class="slide-sub a1">Było → jest. Pod każdą zmianą metody z katalogu COVE, które ją opisują.</p><div class="card-grid cg3 shift-grid a2">${I.shifts.map(([a,b,how,m],i)=>`<article class="card shift" style="--i:${i}"><p class="tr-from">${esc(a)}</p><p class="shift-to"><span aria-hidden="true">→ </span>${esc(b)}</p><p class="card-body">${esc(how)}</p><p class="pills">${pills(m)}</p></article>`).join('')}</div>`],
 ['lekcjaB','Tak może wyglądać lekcja B',()=>{const L=I.lesson;return `<p class="section-label at">Lekcja w praktyce</p><h2 class="slide-title at">${esc(L.label)}</h2><div class="accent-line as"></div><p class="slide-sub a1">${esc(L.goal)}</p><div class="two-col a2"><ol class="tl">${L.steps.map((s,i)=>{return `<li><button type="button" class="tl-item tl-btn" data-action="lstep-go" data-i="${i}"><span class="tl-dot">${i+1}</span><span class="tl-body"><span class="tl-label">${esc(s.title)}</span><span class="tl-desc">${esc(s.method)}</span></span></button></li>`;}).join('')}</ol><div class="accent-col"><h3>Warunki</h3><p>${esc(L.context)}</p><div class="actions">${link(L.url,'Otwórz materiał ZPE','btn btn-primary')}${ext(I.base+'method-1.html','Pytania z kluczem i przypadek','btn btn-ghost')}</div></div></div>`;}],
 ['kroki','Lekcja B krok po kroku',()=>`<h2 class="slide-title at">Lekcja B krok po kroku</h2><div class="accent-line as"></div><div class="stepper a1" role="group" aria-label="Etapy lekcji B">${I.lesson.steps.map((s,i)=>`<button type="button" data-action="lstep" data-i="${i}" aria-pressed="${i===lessonStep}"><b>${i+1}</b>${esc(s.title)}</button>`).join('')}</div><article class="step-panel a2" id="step-panel" aria-live="polite">${lessonStepPanel()}</article><div class="key-box a3">${esc(I.lesson.decision)}</div><p class="foot-note a4">${esc(I.lesson.note)}</p>`],
 ['mat','Ten sam układ w matematyce',()=>`<p class="section-label at">Przedmiot ogólnokształcący</p><h2 class="slide-title at">Ten sam układ: matematyka, zmiana procentowa</h2><div class="accent-line as"></div><p class="slide-sub a1">Kolejność etapów jest ta sama, zmienia się tylko treść. ${link(I.variant.url,'Materiał ZPE „Obliczenia procentowe. Część I”')}</p><div class="mini-table a2">${I.variant.rows.map((r,i)=>`<div class="mt-row"><span class="mt-num">${i+1}</span><strong>${esc(r[0])}</strong><span>${esc(r[1])}</span></div>`).join('')}</div>`],
 ['sprzet','Praktycznie: laptop, iPad, sieć',()=>`<h2 class="slide-title at">Praktycznie: laptop, iPad, sieć</h2><div class="accent-line as"></div><div class="card-grid cg3 a1">${I.devices.map(([ic,t,x])=>`<article class="card"><div class="card-icon" aria-hidden="true">${ic}</div><h3 class="card-title">${esc(t)}</h3><p class="card-body">${esc(x)}</p></article>`).join('')}</div>`],
 ['mapa','Mapa 12 metod',()=>`<h2 class="slide-title at">Mapa 12 metod: co robi uczeń z ZPE?</h2><div class="accent-line as"></div><p class="slide-sub a1">Kliknij kartę, żeby zobaczyć rolę nauczyciela i ograniczenia. Każda metoda ma w katalogu COVE plan lekcji i ocenę siły dowodów.</p><div class="card-grid cg4 a2">${I.methods.map(([n,f,u,te,c])=>`<details class="card mcard"><summary><span class="card-title">${esc(n)}</span><span class="card-body">${esc(u)}</span></summary><dl><dt>Nauczyciel</dt><dd>${esc(te)}</dd><dt>Uwaga</dt><dd>${esc(c)}</dd></dl>${ext(I.base+f,'Opis metody')}</details>`).join('')}</div>`],
 ['warsztat','Ten warsztat działa tak samo',()=>`<h2 class="slide-title at">Ten warsztat działa tak samo</h2><div class="accent-line as"></div><p class="slide-sub a1">Przez większość czasu pracują Państwo sami, podobnie jak uczniowie w lekcji B.</p><div class="tr-list narrow a2">${I.workshop.map(([a,b],i)=>`<article class="tr-item" style="--i:${i}"><p class="tr-from">${esc(a)}</p><span class="tr-arr" aria-hidden="true">→</span><div class="tr-to"><p>${esc(b)}</p></div></article>`).join('')}</div><div class="key-box a3">Dziś to Państwo są uczniami w lekcji B. Zaczynamy od własnego tematu.</div>`]];

// Zadania (styl kursu online)
const MODE={4:'👥 W parach',9:'👥 W parach',10:'👀 Pokaz prowadzącego',11:'💻 Samodzielnie, partner potwierdza'};
function lessonFields(keys){return `<form id="lesson-form" novalidate>${keys.map(k=>field(...D.fields.find(f=>f[0]===k))).join('')}</form><p class="save-status" id="save-status" role="status">${storageOK?'Zapisy pozostają w tej przeglądarce. Trener ich nie otrzymuje.':'Zapis lokalny niedostępny. Pobierz kopię przed zamknięciem.'}</p>`;}
function tool(n){const box=(t,h)=>`<section class="tool-box"><h3>${t}</h3>${h}</section>`;switch(n){
 case 1:return box('Moja lekcja: pierwszy zapis',lessonFields(['topic','group','need'])+`<details><summary>Gotowy przykład 12-minutowej lekcji</summary>${example()}</details>`);
 case 2:return box('Słowniczek',`<div class="card-grid cg3 flat"><article class="card"><h4 class="card-title">Przeglądarka</h4><p class="card-body">Program do otwierania stron, np. Chrome, Edge, Firefox lub Safari.</p></article><article class="card"><h4 class="card-title">Pasek adresu</h4><p class="card-body">Pole u góry okna. Kliknij je, wpisz zpe.gov.pl i naciśnij Enter.</p></article><article class="card"><h4 class="card-title">Karta przeglądarki</h4><p class="card-body">Zakładka z tytułem u góry. W jednej karcie jest szkolenie, w drugiej ZPE.</p></article></div>`);
 case 3:return box('Tak to wygląda w poradniku ZPE',`<div class="fig-grid">${imageFigure('wyszukiwanie.png','Oficjalna ilustracja wyszukiwania materiałów z filtrami. Przykład dotyczy biologii.',D.sources[0][1])}${imageFigure('ulubione-serce.png','Oficjalny przykład pokazujący ikonę serca na stronie materiału',D.sources[1][1])}${imageFigure('ulubione-katalog.png','Oficjalny przykład drogi Katalog, a następnie Ulubione',D.sources[1][1])}</div>`);
 case 4:return box('Role w parze',`<div class="two-col"><div><h4>Osoba ćwicząca</h4>${list(['Otwórz Ulubione.','Wybierz zapisany materiał.','Pokaż dokładny fragment.','Powiedz, co mogliby zrobić z nim uczniowie.'])}</div><div><h4>Osoba wspierająca pyta</h4><ul class="q-list"><li>Na którym kroku teraz jesteś?</li><li>Co widzisz na ekranie i jak to się nazywa?</li><li>Jaki następny krok wskazuje instrukcja?</li></ul><p class="small">Wskazuj instrukcję i daj czas na próbę. Nie przejmuj myszy.</p></div></div>`);
 case 6:return box('Zestaw startowy',resources(true));
 case 7:return box('Formularz „Moja lekcja”',lesson(true));
 case 9:return box('Rama informacji zwrotnej',`<ul class="q-list"><li>„Wiem, co mam zrobić…”</li><li>„Potrzebuję doprecyzowania…”</li></ul>`+lessonFields(['task','answer','revision']));
 case 10:return box('Pokaz prowadzącego',demo());
 case 11:return box('Sprawdzenie',checkView(true));
 case 12:return box('Zachowaj plan',lessonFields(['date','backup'])+`<p id="completeness" role="status"></p><div class="actions">${button('Sprawdź kompletność','validate','secondary')}${link('#/druk-planu','Podgląd i druk planu','button')}${button('Pobierz kopię tekstową','download')}</div>`);
 default:return '';}}
function stage(n){const s=D.stages[n-1],done=state.completed.includes(n),out=s.link&&/^https:/.test(s.link[1]),more=D.extensions[n]||[];return `<div class="lesson-wrap"><header class="lesson-header"><p class="lesson-number">Etap ${n} z 12 · zadanie</p><h2>${esc(s.title)}</h2><div class="lesson-meta"><span class="meta-pill">${MODE[n]||'💻 Na własnym laptopie'}</span></div><p class="lesson-intro">${esc(s.goal)}</p></header><div class="outcome-box"><p class="outcome-title">📌 Gotowe, gdy…</p><p>${esc(s.done)}</p></div><section class="lesson-section"><h3>Zrób teraz</h3><ol class="steps">${s.steps.map(li).join('')}</ol>${out?`<div class="actions">${link(s.link[1],s.link[0],'btn btn-primary')}</div>`:''}</section>${tool(n)}<details class="tip-box"><summary>💡 Potrzebuję podpowiedzi</summary><p>${esc(s.hint)}</p>${[2,3,4,11].includes(n)?link('#/karty','Otwórz ściągę krok po kroku'):''}</details>${more.length?`<details class="tip-box"><summary>📚 Rozszerzenia i materiały na później</summary><div class="actions">${more.map(([label,url])=>link(url,label,'button secondary')).join('')}</div></details>`:''}${s.extra?`<p class="tip-extra">⚡ ${esc(s.extra)}</p>`:''}<label class="done-toggle"><input type="checkbox" data-complete="${n}" ${done?'checked':''}><span>Oznaczam etap jako wykonany</span></label><p class="small">To Twoja notatka, nie ocena trenera.</p></div>`;}
function intro(){return INTRO.map(x=>x[2]()).join('');}
function stageNotes(n){const s=D.stages[n-1];return `<dl><dt>Przygotuj</dt><dd>${esc(s.prep)}</dd><dt>Powiedz</dt><dd>„${esc(s.say)}”</dd><dt>Poprowadź</dt><dd>${esc(s.run)}</dd><dt>Typowa trudność</dt><dd>${esc(s.error)}</dd><dt>Jak pomóc</dt><dd>${esc(s.help)}</dd></dl>`;}

SLIDES.push({key:'start',kind:'title',section:'Start',title:'ZPE bez pośpiechu',html:titleSlide,notes:()=>'<p>Powitanie. Sprawdź, czy wszyscy mają włączony laptop i otwartą tę stronę. Przechodzenie: strzałki, PageDown/PageUp (pilot), klawisz N pokazuje i ukrywa notatki, M otwiera spis slajdów.</p>'});
SLIDES.push({key:'plan',kind:'content',section:'Start',title:'Plan warsztatu',html:agendaSlide,notes:()=>'<p>Najwyżej pół minuty. Powiedz, że każdy etap kończy się czymś, co uczestnik zrobił sam.</p>'});
D.stages.forEach((s,i)=>{const n=i+1,section=`Etap ${n} · ${s.title}`;
 if(isBreak(n)){SLIDES.push({key:'etap-'+n,kind:'break',stage:n,section,title:s.title,html:()=>breakSlide(n),notes:()=>stageNotes(n)});return;}
 SLIDES.push({key:'etap-'+n,kind:'divider',stage:n,section,title:`Etap ${n}: ${s.title}`,html:()=>divider(n),notes:()=>stageNotes(n)});
 if(n===1)INTRO.forEach(([key,title,html])=>SLIDES.push({key,kind:'content',stage:1,section:'Etap 1 · Wstęp',title,html,notes:()=>`<p>${esc(I.notes[key])}</p>`}));
 SLIDES.push({key:'zadanie-'+n,kind:'task',stage:n,section,title:'Zadanie: '+s.title,html:()=>stage(n),notes:()=>stageNotes(n)});});
SLIDES.push({key:'koniec',kind:'end',section:'Zakończenie',title:'Zakończenie',html:endSlide,notes:()=>'<p>Zbierz papierowe karty 5. Zapowiedz trzy pytania po 7–14 dniach. Przypomnij, że strona niczego nie wysyła.</p>'});

const PAGES={'/centrum-materialow':materialsCenter,'/materialy':()=>resources(),'/moja-lekcja':()=>lesson(),'/baza-wiedzy':knowledge,'/poradniki':guides,'/karty':()=>cards(),'/druk-kart':()=>cards(true),'/trener':()=>trainer(),'/druk-trenera':()=>trainer(true),'/sprawdzenie':()=>checkView(),'/druk-sprawdzenia':printCheck,'/druk-planu':printLesson,'/zrodla':sources,'/pokaz':()=>`<div class="wrap"><h1>Od materiału do informacji zwrotnej</h1>${demo()}</div>`};
function slideNo(route){const m=route.match(/^\/s\/(\d+)$/);if(m)return Math.max(1,Math.min(SLIDES.length,+m[1]));const e=route.match(/^\/etap\/(\d+)$/);if(e&&+e[1]>=1&&+e[1]<=12)return idx('etap-'+e[1]);if(route==='/wstep')return idx('teza');if(route==='/')return 1;return 0;}
function docFooter(){return `<footer class="doc-footer">${logos()}<nav class="footer-links" aria-label="Nawigacja w stopce">${link('#/centrum-materialow','Wszystkie materiały')}${link('#/baza-wiedzy','Baza wiedzy ZPE')}${link('#/poradniki','Indeks 11 poradników')}${ext('https://metodyka.covepolska.pl/','Katalog metod COVE')}${link('#/zrodla','Źródła i informacje o szkoleniu')}${ext('https://covepolska.pl/deklaracja-dostepnosci/','Deklaracja dostępności')}</nav></footer>`;}
function setText(id,t){const n=document.getElementById(id);if(n)n.textContent=t;}
function renderNotes(){const n=document.getElementById('notes'),b=document.getElementById('notes-btn');if(b)b.setAttribute('aria-pressed',String(notesOpen));if(!n)return;n.hidden=!(notesOpen&&mode==='deck');if(mode==='deck')n.innerHTML=`<h2>Notatki prowadzącego · slajd ${current}</h2>${SLIDES[current-1].notes()}`;document.body.classList.toggle('with-notes',notesOpen&&mode==='deck');}
function swap(html,dir){const apply=()=>{main.innerHTML=html;main.scrollTop=0;};const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(dir&&!reduce&&typeof document.startViewTransition==='function'){document.documentElement.dataset.dir=dir;document.startViewTransition(apply);}else apply();}
function render(){clearInterval(timerId);closeMenu();const route=location.hash.slice(1)||'/',n=slideNo(route),bar=document.getElementById('progress-bar');
 if(n){const dir=mode==='deck'&&n!==current?(n>current?'fwd':'bwd'):'';mode='deck';current=n;if(n>1){state.slide=n;if(storageOK)save();}const s=SLIDES[n-1];document.body.classList.add('deck');document.body.classList.remove('doc');
  swap(`<section class="slide is-on slide--${s.kind}" aria-roledescription="slajd" aria-label="Slajd ${n} z ${SLIDES.length}: ${esc(s.title)}"><div class="slide-inner">${s.html()}</div></section>`,dir);
  if(bar)bar.style.width=(n/SLIDES.length*100)+'%';setText('slide-counter',`${n} / ${SLIDES.length}`);setText('slide-section',s.section);
  const prev=document.getElementById('btn-prev'),next=document.getElementById('btn-next');if(prev){prev.disabled=n===1;prev.hidden=false;}if(next)next.textContent=n===SLIDES.length?'Do początku ↺':'Dalej →';
  document.title=s.title+' | ZPE bez pośpiechu';announce(`Slajd ${n} z ${SLIDES.length}: ${s.title}`);}
 else{mode='doc';document.body.classList.add('doc');document.body.classList.remove('deck');const page=PAGES[route];main.innerHTML=(page?page():`<div class="wrap"><h1>Nie ma takiej strony</h1><p>Wróć do szkolenia, aby kontynuować.</p></div>`)+docFooter();window.scrollTo(0,0);
  if(bar)bar.style.width='0';setText('slide-counter','Materiały');setText('slide-section','Poza prezentacją');const prev=document.getElementById('btn-prev'),next=document.getElementById('btn-next');if(prev)prev.hidden=true;if(next)next.textContent=`← Wróć do slajdu ${state.slide}`;document.title=(main.querySelector('h1')?.textContent||'Materiały')+' | ZPE bez pośpiechu';}
 renderNotes();main.focus({preventScroll:true});}
// Spis slajdów i materiałów
let menuOpen=false;
function renderMenu(){const box=document.getElementById('menu-list');if(!box)return;let last='';box.innerHTML=SLIDES.map((s,i)=>{const head=s.section!==last?`${last?'</ol>':''}<h3>${esc(s.section)}</h3><ol>`:'';last=s.section;const done=s.kind==='task'&&state.completed.includes(s.stage);return `${head}<li><a href="#/s/${i+1}"${mode==='deck'&&i+1===current?' aria-current="step"':''}><span class="mnum">${i+1}</span>${esc(s.title)}${done?' <span class="ok">✓</span>':''}</a></li>`;}).join('')+'</ol>';}
function openMenu(){const m=document.getElementById('menu');if(!m)return;renderMenu();m.hidden=false;menuOpen=true;document.getElementById('menu-btn')?.setAttribute('aria-expanded','true');m.querySelector('[aria-current]')?.scrollIntoView({block:'center'});m.querySelector('.menu-close')?.focus();}
function closeMenu(){const m=document.getElementById('menu');if(!m||!menuOpen)return;m.hidden=true;menuOpen=false;document.getElementById('menu-btn')?.setAttribute('aria-expanded','false');}
function tick(){const t=document.getElementById('timer');if(!t){clearInterval(timerId);return;}const s=Math.max(0,+t.dataset.sec-1);t.dataset.sec=s;t.textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(!s){clearInterval(timerId);t.classList.add('over');announce('Koniec przerwy.');}}
window.addEventListener('hashchange',render);
main.addEventListener('input',e=>{const t=e.target;if(t.closest('#lesson-form')&&D.fields.some(f=>f[0]===t.name)){state.lesson[t.name]=t.value;save();if(t.name==='url'){const u=document.getElementById('url-error');if(u)u.textContent='';}}if(t.closest('#assessment')){if(t.name==='partner'||t.name==='support')state[t.name]=t.value;else if(t.name.startsWith('check-'))state.assessment[t.name.slice(6)]=t.value;save();}});
main.addEventListener('submit',e=>e.preventDefault());
main.addEventListener('change',e=>{if(e.target.dataset.complete){const n=+e.target.dataset.complete;state.completed=state.completed.filter(v=>v!==n);if(e.target.checked)state.completed.push(n);save();announce(e.target.checked?'Oznaczono etap jako wykonany.':'Usunięto oznaczenie wykonania.');}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();});
const INTERACTIVE='a,button,input,textarea,select,label,summary,details,figure,table,.poll,.stepper,.reveal,.step-panel,.tool-box,.card-grid';
main.addEventListener('click',e=>{const external=e.target.closest('a[target="zpe-material"]');if(external&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();openMaterial(external.href);return;}const b=e.target.closest('[data-action]');
 if(!b){const s=SLIDES[current-1];if(mode==='deck'&&s.kind!=='task'&&!e.target.closest(INTERACTIVE)&&!String(window.getSelection?.()||''))go(current+1);return;}
 switch(b.dataset.action){
case 'next':go(current+1);break;
case 'print':window.print();break;
case 'reveal':{const a=document.getElementById(b.getAttribute('aria-controls')),open=a.hidden;a.hidden=!open;b.setAttribute('aria-expanded',String(open));b.textContent=open?'Ukryj odpowiedź':'Pokaż odpowiedź';break;}
case 'poll':main.querySelectorAll('.poll-opt').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));break;
case 'poll-show':{main.querySelectorAll('.poll-opt').forEach(o=>o.classList.add(+o.dataset.i===I.poll.correct?'correct':'wrong'));document.getElementById('poll-result').hidden=false;b.disabled=true;announce('Poprawna odpowiedź: '+I.poll.options[I.poll.correct]);break;}
case 'lstep-go':lessonStep=+b.dataset.i;go(idx('kroki'));break;
case 'lstep':{lessonStep=+b.dataset.i;main.querySelectorAll('.stepper button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('step-panel').innerHTML=lessonStepPanel();break;}
case 'timer':{clearInterval(timerId);timerId=setInterval(tick,1000);b.textContent='Odliczanie trwa';b.disabled=true;break;}
case 'filter':{filter=b.dataset.filter;const box=document.getElementById('resources-box');box.outerHTML=resources(box.dataset.embed==='1');main.querySelector(`[data-filter="${filter}"]`)?.focus();announce('Widoczne materiały: '+D.resources.filter(r=>filter==='all'||r.kind===filter).length);break;}
case 'select-resource':{const r=D.resources.find(x=>x.id===b.dataset.id);state.lesson.title=r.title;state.lesson.url=r.url;save();location.hash='/s/'+idx('zadanie-7');announce('Wpisano tytuł i link. Uzupełnij dokładny fragment samodzielnie.');break;}
case 'open-lesson':{const u=(state.lesson.url||'').trim();if(!isZpe(u)){document.getElementById('url-error').textContent='Wklej pełny adres materiału z https://zpe.gov.pl/. Sam tytuł albo adres innej strony nie wystarczy.';document.getElementById('f-url').focus();}else{document.getElementById('url-error').textContent='Adres ma poprawny format ZPE. Sprawdź otwarty materiał; nie weryfikujemy jego zawartości automatycznie.';openMaterial(u);}break;}
case 'validate':{const required=['topic','group','goal','title','url','fragment','duration','task','answer','check','date'],missing=required.filter(k=>!state.lesson[k]?.trim());const n=document.getElementById('completeness');n.textContent=missing.length?'Uzupełnij: '+missing.map(k=>D.fields.find(f=>f[0]===k)[1]).join('; ')+'.':!isZpe(state.lesson.url)?'Popraw link: potrzebny jest pełny adres HTTPS w domenie ZPE.':'Wszystkie podstawowe pola są wypełnione. Teraz otwórz link i sprawdź polecenie z partnerem; formularz nie ocenia jego poprawności.';n.scrollIntoView({block:'center'});break;}
case 'download':{const text='MOJA LEKCJA Z ZPE\n\n'+D.fields.map(([k,t])=>t+'\n'+(state.lesson[k]||'Do uzupełnienia')).join('\n\n');const url=URL.createObjectURL(new Blob(['﻿'+text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='moja-lekcja-z-ZPE.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Przygotowano plik moja-lekcja-z-ZPE.txt.');break;}
}});
// Pasek dolny, spis i notatki
document.addEventListener('click',e=>{if(e.target.closest('#menu a'))closeMenu();const u=e.target.closest('[data-ui]');if(!u)return;switch(u.dataset.ui){
case 'prev':go(current-1);break;
case 'next':if(mode==='doc')go(state.slide);else go(current===SLIDES.length?1:current+1);break;
case 'notes':notesOpen=!notesOpen;try{localStorage.setItem('zpe-notes',notesOpen?'1':'0');}catch{}renderNotes();break;
case 'menu':menuOpen?closeMenu():openMenu();break;
case 'menu-close':closeMenu();document.getElementById('menu-btn')?.focus();break;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuOpen){closeMenu();document.getElementById('menu-btn')?.focus();return;}if(mode!=='deck'||e.altKey||e.ctrlKey||e.metaKey)return;const t=e.target;if(t.closest?.('input,textarea,select,[contenteditable]'))return;
 const k=e.key,more=d=>d>0?main.scrollTop+main.clientHeight<main.scrollHeight-4:main.scrollTop>4;
 if(k==='ArrowRight'){e.preventDefault();go(current+1);}else if(k==='ArrowLeft'){e.preventDefault();go(current-1);}
 else if(k==='PageDown'||(k===' '&&!t.closest?.('button,a,summary'))){if(more(1))return;e.preventDefault();go(current+1);}
 else if(k==='PageUp'){if(more(-1))return;e.preventDefault();go(current-1);}
 else if(k==='Home'&&!menuOpen){e.preventDefault();go(1);}else if(k==='End'&&!menuOpen){e.preventDefault();go(SLIDES.length);}
 else if(k==='n'||k==='N'){notesOpen=!notesOpen;try{localStorage.setItem('zpe-notes',notesOpen?'1':'0');}catch{}renderNotes();}
 else if(k==='m'||k==='M'){menuOpen?closeMenu():openMenu();}});
let touchX=0,touchY=0;
main.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;touchY=e.changedTouches[0].clientY;},{passive:true});
main.addEventListener('touchend',e=>{if(mode!=='deck'||e.target.closest('input,textarea,select,table,.stepper,.table-wrap,.poll'))return;const dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)<60||Math.abs(dx)<Math.abs(dy)*1.5)return;go(dx<0?current+1:current-1);},{passive:true});
render();

const themeControl=document.getElementById('theme');
try{themeControl.value=localStorage.getItem('zpe-theme')||'auto';}catch{}
function applyTheme(){document.documentElement.dataset.theme=themeControl.value;}
applyTheme();themeControl.addEventListener('change',()=>{applyTheme();try{localStorage.setItem('zpe-theme',themeControl.value);}catch{}});
